    private void injectStudioTab(View v){if(!(v instanceof ViewGroup))return;ViewGroup g=(ViewGroup)v;if(g instanceof LinearLayout&&g.getParent() instanceof HorizontalScrollView){for(int i=0;i<g.getChildCount();i++)if(TAB.equals(g.getChildAt(i).getTag()))return;Button b=button80(tr80("Studio"));b.setTag(TAB);b.setOnClickListener(x->showStudio());g.addView(b);return;}for(int i=0;i<g.getChildCount();i++)injectStudioTab(g.getChildAt(i));}
