        String[] moments={"All","Talking","Reaction","Action","Close-up","Silent reaction"};box.addView(text(tr80("Moment filter"),12,true));Spinner moment=spinner(moments,x.getString("v080_moment","All"));moment.setOnItemSelectedListener(listener(pos->x.edit().putString("v080_moment",moments[pos]).apply()));box.addView(moment);
