    private void renameActor(String key,int id){EditText e=new EditText(this);e.setText(studio.actorName(key,id));new AlertDialog.Builder(this).setTitle(tr80("Rename Actor")).setView(e).setNegativeButton(tr80("Cancel"),null).setPositiveButton(tr80("Save"),(d,w)->{studio.setActorName(key,id,e.getText().toString());showStudio();}).show();}
    private void mergeSelected(String key){ActorScanStore.ScanState s=scan();LinkedHashSet<Integer> ids=studio.selectedActors(key);if(s==null||ids.size()<2){toast(tr80("Select at least two actors"));return;}new AlertDialog.Builder(this).setTitle(tr80("Merge selected actors?" )).setMessage(tr80("The first selected actor becomes the master group. This can be undone only by rescanning." )).setNegativeButton(tr80("Cancel"),null).setPositiveButton(tr80("Merge"),(d,w)->worker80.execute(()->{try{Iterator<Integer>it=ids.iterator();int masterId=it.next();ActorScanStore.Cluster master=s.byId(masterId);if(master==null)return;while(it.hasNext()){int id=it.next();ActorScanStore.Cluster other=s.byId(id);if(other==null)continue;merge(master,other);s.clusters.remove(other);}s.selectedClusterId=masterId;setSelectedId(masterId);new ActorScanStore(this).save(s);studio.saveSelectedActors(key,Collections.singleton(masterId));runOnUiThread(this::showStudio);}catch(Throwable e){runOnUiThread(()->toast("Merge: "+e.getClass().getSimpleName()));}})).show();}
    private void merge(ActorScanStore.Cluster a,ActorScanStore.Cluster b){int ca=Math.max(1,a.count),cb=Math.max(1,b.count);if(a.centroid==null)a.centroid=b.centroid==null?null:b.centroid.clone();else if(b.centroid!=null&&a.centroid.length==b.centroid.length){for(int i=0;i<a.centroid.length;i++)a.centroid[i]=(a.centroid[i]*ca+b.centroid[i]*cb)/(ca+cb);FaceEngine.normalize(a.centroid);}a.count+=b.count;a.qualitySum+=b.qualitySum;a.hits.addAll(b.hits);a.hits.sort(Comparator.comparingLong(h->h.t));a.videosSeen.addAll(b.videosSeen);a.thumbs.addAll(b.thumbs);a.thumbQualities.addAll(b.thumbQualities);while(a.thumbs.size()>8)a.thumbs.remove(a.thumbs.size()-1);while(a.thumbQualities.size()>8)a.thumbQualities.remove(a.thumbQualities.size()-1);a.lastSeenMs=Math.max(a.lastSeenMs,b.lastSeenMs);}
    private void splitSelected(String key){ActorScanStore.ScanState s=scan();LinkedHashSet<Integer> ids=studio.selectedActors(key);if(s==null||ids.isEmpty()){toast(tr80("Select one actor first"));return;}int id=ids.iterator().next();ActorScanStore.Cluster src=s.byId(id);if(src==null)return;float threshold=Math.max(.42f,p().getFloat("cluster_threshold",.58f));ArrayList<ActorScanStore.Hit> weak=new ArrayList<>();for(ActorScanStore.Hit h:src.hits)if(h.score<threshold-.03f)weak.add(h);if(weak.size()<2||weak.size()>=src.hits.size()*.75){toast(tr80("No safe weak-match split found"));return;}worker80.execute(()->{try{int nid=0;for(ActorScanStore.Cluster q:s.clusters)nid=Math.max(nid,q.id+1);ActorScanStore.Cluster n=new ActorScanStore.Cluster(nid);n.centroid=src.centroid==null?null:src.centroid.clone();for(ActorScanStore.Hit h:weak){n.hits.add(h);n.videosSeen.add(h.videoIndex);n.qualitySum+=h.quality;}n.count=weak.size();src.hits.removeAll(weak);src.count=Math.max(1,src.hits.size());src.qualitySum=0;for(ActorScanStore.Hit h:src.hits)src.qualitySum+=h.quality;s.clusters.add(n);new ActorScanStore(this).save(s);runOnUiThread(this::showStudio);}catch(Throwable e){runOnUiThread(()->toast("Split: "+e.getClass().getSimpleName()));}});}
    private void feedbackSelected(String key,boolean correct){LinkedHashSet<Integer> ids=studio.selectedActors(key);if(ids.isEmpty()){int id=selectedId();if(id>=0)ids.add(id);}if(ids.isEmpty()){toast(tr80("Select an actor first"));return;}for(int id:ids)studio.feedback(key,id,correct?"correct":"wrong");float th=p().getFloat("cluster_threshold",.58f);th+=correct?-.006f:.012f;th=Math.max(.48f,Math.min(.78f,th));p().edit().putFloat("cluster_threshold",th).apply();toast(tr80("Correction learned for this project"));}

    private void composeQueue(String key,ActorScanStore.ScanState s,List<Uri> videos,Uri out){if(key.isEmpty()||s==null){toast(tr80("Run Actor Scan first"));return;}if(out==null){toast(tr80("Choose output folder first"));return;}LinkedHashSet<Integer> selected=studio.selectedActors(key);if(selected.isEmpty()){int id=selectedId();if(id>=0)selected.add(id);}if(selected.isEmpty()){toast(tr80("Select an actor first"));return;}final LinkedHashSet<Integer> ids=new LinkedHashSet<>(selected);worker80.execute(()->{try{ArrayList<V080ExportQueue.Job> jobs=new ArrayList<>();String mode=p().getString("v080_multi_mode","Separate");boolean together="Together only".equals(mode);long clip=Math.max(2000,p().getInt("clip_seconds",5)*1000L);boolean exact=p().getBoolean("v080_exact",false);String moment=p().getString("v080_moment","All");int top=p().getInt("v080_top_n",20);String preset=p().getString("v080_preset","Instagram 1:1");String aspect=aspectForPreset(preset);String codec=codecForPreset(preset);boolean track=p().getBoolean("smart_tracking",true);boolean safe=p().getBoolean("safe_zone",true);boolean max=p().getBoolean("max_quality",true)||preset.startsWith("Maximum");for(int vi=0;vi<videos.size();vi++){long duration=duration(videos.get(vi));if(duration<2000)continue;if(together){addJobsFor(jobs,key,videos.get(vi),out,vi,s,ids,true,clip,exact,moment,top,preset,aspect,codec,track,safe,max);}else for(int id:ids)addJobsFor(jobs,key,videos.get(vi),out,vi,s,Collections.singleton(id),false,clip,exact,moment,top,preset,aspect,codec,track,safe,max);}if(jobs.isEmpty())throw new IllegalStateException("No qualifying clips");queue.append(jobs);studio.saveSelectedActors(key,ids);runOnUiThread(()->new AlertDialog.Builder(this).setTitle(tr80("Render Queue Ready")).setMessage(jobs.size()+" "+tr80("ranked clip(s) added")).setNegativeButton(tr80("Later"),null).setPositiveButton(tr80("Start now"),(d,w)->startExportService(V080ExportService.ACTION_START)).show());}catch(Throwable e){runOnUiThread(()->toast(tr80("Queue build failed")+": "+e.getMessage()));}});}
    private void addJobsFor(List<V080ExportQueue.Job> outJobs,String key,Uri uri,Uri outTree,int vi,ActorScanStore.ScanState s,Collection<Integer> ids,boolean together,long clip,boolean exact,String moment,int top,String preset,String aspect,String codec,boolean track,boolean safe,boolean max){ArrayList<ActorScanStore.Hit> hits=V080SceneAnalyzer.collect(s,ids,vi,together);List<V080SceneAnalyzer.Segment> segs=V080SceneAnalyzer.build(hits,duration(uri),clip,scanSample(s),exact,moment,top);String idText=joinIds(ids);int no=0;for(V080SceneAnalyzer.Segment seg:segs){V080ExportQueue.Job j=new V080ExportQueue.Job();j.projectKey=key;j.sourceUri=uri.toString();j.outputTree=outTree.toString();j.videoIndex=vi;j.actorIds=idText;j.mode=together?"together":"separate";j.startMs=seg.startMs;j.endMs=seg.endMs;j.score=seg.score;j.aspect=aspect;j.preset=preset;j.codec=codec;j.tracking=track;j.safeZone=safe;j.maxQuality=max;j.outputName=String.format(Locale.US,"%s_%s_A%s_%02d_%dms.mp4",seg.rank,safeBase(displayName(uri)),idText.replace(',','-'),++no,seg.startMs);outJobs.add(j);}}

    private void previewCurrent(String key,ActorScanStore.ScanState s,List<Uri> videos){if(s==null||videos.isEmpty()){toast(tr80("Scan and select videos first"));return;}LinkedHashSet<Integer> ids=studio.selectedActors(key);if(ids.isEmpty()){int id=selectedId();if(id>=0)ids.add(id);}if(ids.isEmpty()){toast(tr80("Select an actor first"));return;}final LinkedHashSet<Integer> chosen=new LinkedHashSet<>(ids);worker80.execute(()->{Bitmap original=null,cropped=null;MediaMetadataRetriever mr=new MediaMetadataRetriever();try{Uri uri=videos.get(0);boolean together="Together only".equals(p().getString("v080_multi_mode","Separate"));ArrayList<ActorScanStore.Hit> hits=V080SceneAnalyzer.collect(s,chosen,0,together);List<V080SceneAnalyzer.Segment> segs=V080SceneAnalyzer.build(hits,duration(uri),Math.max(2000,p().getInt("clip_seconds",5)*1000L),scanSample(s),p().getBoolean("v080_exact",false),p().getString("v080_moment","All"),1);if(segs.isEmpty())throw new IllegalStateException("No preview scene");V080SceneAnalyzer.Segment seg=segs.get(0);long mid=(seg.startMs+seg.endMs)/2;mr.setDataSource(this,uri);original=mr.getFrameAtTime(mid*1000L,MediaMetadataRetriever.OPTION_CLOSEST);if(original==null)throw new IOException("Frame unavailable");cropped=previewCrop(original,seg.hits,aspectForPreset(p().getString("v080_preset","Instagram 1:1")));Bitmap a=original,b=cropped;runOnUiThread(()->showPreviewDialog(a,b,seg));original=null;cropped=null;}catch(Throwable e){Bitmap a=original,b=cropped;if(a!=null)a.recycle();if(b!=null&&b!=a)b.recycle();runOnUiThread(()->toast(tr80("Preview failed")+": "+e.getClass().getSimpleName()));}finally{try{mr.release();}catch(Throwable ignored){}}});}
    private Bitmap previewCrop(Bitmap src,List<ActorScanStore.Hit> hits,String aspectName){float target="Original".equals(aspectName)?src.getWidth()/(float)src.getHeight():aspectValue(aspectName);double sx=0,sy=0,w=0;for(ActorScanStore.Hit h:hits){double q=.2+h.quality;sx+=h.cx*q;sy+=h.cy*q;w+=q;}float cx=w==0?.5f:(float)(sx/w),cy=w==0?.5f:(float)(sy/w);int sw=src.getWidth(),sh=src.getHeight(),cw=sw,ch=sh;if(sw/(float)sh>target)cw=Math.max(1,Math.round(sh*target));else ch=Math.max(1,Math.round(sw/target));int x=Math.round(cx*sw-cw/2f),y=Math.round(cy*sh-ch*.42f);x=Math.max(0,Math.min(sw-cw,x));y=Math.max(0,Math.min(sh-ch,y));return Bitmap.createBitmap(src,x,y,cw,ch);}
    private void showPreviewDialog(Bitmap original,Bitmap crop,V080SceneAnalyzer.Segment seg){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(8),dp(8),dp(8),dp(8));box.addView(text(tr80("Original"),12,true));ImageView a=new ImageView(this);a.setAdjustViewBounds(true);a.setImageBitmap(original);box.addView(a,new LinearLayout.LayoutParams(-1,dp(190)));box.addView(text(tr80("Smart Crop Preview")+" • "+seg.rank+" "+Math.round(seg.score)+"/100 • "+seg.expression,12,true));ImageView b=new ImageView(this);b.setAdjustViewBounds(true);b.setScaleType(ImageView.ScaleType.CENTER_INSIDE);b.setImageBitmap(crop);box.addView(b,new LinearLayout.LayoutParams(-1,dp(220)));AlertDialog d=new AlertDialog.Builder(this).setTitle(tr80("Before / After")).setView(box).setPositiveButton("OK",null).create();d.setOnDismissListener(x->{try{if(original!=null&&!original.isRecycled())original.recycle();}catch(Throwable ignored){}try{if(crop!=null&&crop!=original&&!crop.isRecycled())crop.recycle();}catch(Throwable ignored){}});d.show();}

    private void autoTune(){worker80.execute(()->{try{android.app.ActivityManager am=(android.app.ActivityManager)getSystemService(ACTIVITY_SERVICE);android.app.ActivityManager.MemoryInfo mi=new android.app.ActivityManager.MemoryInfo();am.getMemoryInfo(mi);int cores=Runtime.getRuntime().availableProcessors();long gb=mi.totalMem/(1024L*1024*1024);String mode=(cores>=8&&gb>=6)?"Balanced":(cores>=6&&gb>=4)?"Balanced":"Quick";boolean hevc=V070CodecAdvisor.hasHardware("video/hevc");p().edit().putString("speed_mode_v070",mode).putBoolean("two_pass_scan_v070",true).putBoolean("landmark_on_demand_v070",true).putBoolean("incremental_cache_v070",true).putBoolean("parallel_prefetch_v070",cores>=6).putString("tracking_motion_v061",cores>=8?"Slow":"Fixed actor average").putBoolean("dynamic_zoom_v050",false).putString("codec_best_v070",hevc?"HEVC":"AVC").apply();String msg="CPU "+cores+" • RAM ~"+gb+" GB • "+V070CodecAdvisor.hardwareSummary()+"\n"+tr80("Recommended")+": "+mode+" / "+(hevc?"HEVC":"AVC");runOnUiThread(()->new AlertDialog.Builder(this).setTitle(tr80("Auto Tune Complete")).setMessage(msg).setPositiveButton("OK",null).show());}catch(Throwable e){runOnUiThread(()->toast("Tune: "+e.getClass().getSimpleName()));}});}

