    private String displayName(Uri u){try(Cursor c=getContentResolver().query(u,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst()){String s=c.getString(0);if(s!=null&&!s.isEmpty())return s;}}catch(Throwable ignored){}return u.getLastPathSegment()==null?"video":u.getLastPathSegment();}
    private String safeBase(String n){int d=n.lastIndexOf('.');if(d>0)n=n.substring(0,d);return n.replaceAll("[^A-Za-z0-9._-]+","_");}
