    private String aspectForPreset(String p){if(p==null)return"1:1";if(p.contains("4:5"))return"4:5";if(p.contains("9:16")||p.contains("Reels")||p.contains("Story"))return"9:16";if(p.startsWith("Original"))return"Original";return"1:1";}private String codecForPreset(String p){if(p!=null&&p.contains("Telegram"))return"AVC";return"Auto";}private float aspectValue(String s){if("9:16".equals(s))return 9f/16f;if("4:5".equals(s))return 4f/5f;if("16:9".equals(s))return 16f/9f;return 1f;}

